#include "stdafx.h"#include "HcdDebugDoc.h"#include "HcdDebug.h"#include <io.h>#include <vector>// KHcdDebugDocIMPLEMENT_DYNCREATE(KHcdDebugDoc, CDocument)KHcdDebugDoc::KHcdDebugDoc(): m_ppCtrls( NULL ), m_cCtrls( 0 ), m_pParams( NULL ){  m_Notifiers.insert( notifiers_vector::value_type( eSelectedSheet, CreateNotifier() ) );  m_Notifiers.insert( notifiers_vector::value_type( eSelectedPage, CreateNotifier() ) );  m_Notifiers.insert( notifiers_vector::value_type( eSelectedBlock, CreateNotifier() ) );}BOOL KHcdDebugDoc::OnNewDocument(){	if (!CDocument::OnNewDocument())		return FALSE;	return TRUE;}KHcdDebugDoc::~KHcdDebugDoc(){}notifier_ptr KHcdDebugDoc::CreateNotifier(){  return notifier_ptr( new notifier(this) );}INotifier* KHcdDebugDoc::GetEventNotifier( int id ){  notifiers_vector::iterator iter = m_Notifiers.find( id );  if( iter==m_Notifiers.end() )  {    ASSERT( 0 );    return NULL;  }  return iter->second.get();}BEGIN_MESSAGE_MAP(KHcdDebugDoc, CDocument)END_MESSAGE_MAP()// KHcdDebugDoc diagnostics#ifdef _DEBUGvoid KHcdDebugDoc::AssertValid() const{	CDocument::AssertValid();}#ifndef _WIN32_WCEvoid KHcdDebugDoc::Dump(CDumpContext& dc) const{	CDocument::Dump(dc);}#endif#endif //_DEBUG#ifndef _WIN32_WCE// KHcdDebugDoc serializationvoid KHcdDebugDoc::Serialize(CArchive& ar){	if (ar.IsStoring())	{		// TODO: add storing code here	}	else	{		// TODO: add loading code here	}}#endif